sun = 8
# If sun is above 5, print Grow! Otherwise print Wait
if sun > 5:
    print("Grow!")
else:
    print("Wait")

# Water 3 plants, one line each
for i in range(3):
    print("Water plant", i + 1)

prices = {"sunflower": 20, "tulip": 30}
# Print the price of a sunflower
print(prices["sunflower"])

garden_bed = ["flower", "weed", "flower", "weed", "flower"]
# Loop over garden_bed and print only items that equal 'flower'
for item in garden_bed:
    if item == "flower":
        print(item)

# Plant a 2x3 garden grid: Rows 1 to 2, Columns 1 to 3
for row in range(1, 3):
    for col in range(1, 4):
        print(f"Plot ({row},{col})")
